function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50000) return 's must have 1 to 50000 characters.';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code < 32 || code > 126) return 's may only contain printable ASCII characters.';
  }
  if (s[0] === ' ' || s[s.length - 1] === ' ') return 's cannot start or end with a space.';
  if (s.includes('  ')) return 'Words must be separated by a single space.';
  return null;
}

