function reverseWords(s) {
  const chars = s.split('');
  let start = 0;
  for (let end = 0; end <= chars.length; end++) {
    if (end < chars.length && chars[end] !== ' ') {
      continue;
    }
    let left = start;
    let right = end - 1;
    while (left < right) {
      const temp = chars[left];
      chars[left] = chars[right];
      chars[right] = temp;
      left++;
      right--;
    }
    start = end + 1;
  }
  return chars.join('');
}

