function generate(rand, size) {
  const wordChar = () => String.fromCharCode(33 + Math.floor(rand() * 94));
  const smallAlphabet = "ab'.Z9";
  const limit = size === 'large' ? 9000 + Math.floor(rand() * 1000) : 1 + Math.floor(rand() * 12);
  const words = [];
  let length = 0;
  while (length < limit || words.length === 0) {
    const maxWord = size === 'large' ? 1 + Math.floor(rand() * 15) : 1 + Math.floor(rand() * 5);
    let word = '';
    for (let i = 0; i < maxWord; i++) word += size === 'large' ? wordChar() : smallAlphabet[Math.floor(rand() * smallAlphabet.length)];
    const extra = (words.length ? 1 : 0) + word.length;
    if (words.length && length + extra > limit) break;
    words.push(word);
    length += extra;
  }
  return [words.join(' ')];
}
